  ('XAU:GBCB4WO6J4ET55RWK2SVX76LUQ4PQ7TCDHG2YFILQML7D6XR3HACLXAU', 'classic', 'XAU:GBCB4WO6J4ET55RWK2SVX76LUQ4PQ7TCDHG2YFILQML7D6XR3HACLXAU', 'XAU', 7),
  ('XRF:GCHI6I3X62ND5XUMWINNNKXS2HPYZWKFQBZZYBSMHJ4MIP2XJXSZTXRF', 'classic', 'XRF:GCHI6I3X62ND5XUMWINNNKXS2HPYZWKFQBZZYBSMHJ4MIP2XJXSZTXRF', 'XRF', 7),
  ('XRP:GBVOL67TMUQBGL4TZYNMY3ZQ5WGQYFPFD5VJRWXR72VA33VFNL225PL5', 'classic', 'XRP:GBVOL67TMUQBGL4TZYNMY3ZQ5WGQYFPFD5VJRWXR72VA33VFNL225PL5', 'XRP', 7),
  ('XRP:GBXRPL45NPHCVMFFAYZVUVFFVKSIZ362ZXFP7I2ETNQ3QKZMFLPRDTD5', 'classic', 'XRP:GBXRPL45NPHCVMFFAYZVUVFFVKSIZ362ZXFP7I2ETNQ3QKZMFLPRDTD5', 'XRP', 7),
  ('XTAR:GAORYJ3KBDGIM7FFSKVUJHJ5NEFWIRDIAGGBJBJS7TY6ECZS53257IG4', 'classic', 'XTAR:GAORYJ3KBDGIM7FFSKVUJHJ5NEFWIRDIAGGBJBJS7TY6ECZS53257IG4', 'XTAR', 7),
  ('YBX:GBUYYBXWCLT2MOSSHRFCKMEDFOVSCAXNIEW424GLN666OEXHAAWBDYMX', 'classic', 'YBX:GBUYYBXWCLT2MOSSHRFCKMEDFOVSCAXNIEW424GLN666OEXHAAWBDYMX', 'YBX', 7),
  ('ZINC:GCJXFDVEEFGQYBUCYD6XVEZJEHBD2CDIGBFJWX7UWAMYCO5CRRAMMETL', 'classic', 'ZINC:GCJXFDVEEFGQYBUCYD6XVEZJEHBD2CDIGBFJWX7UWAMYCO5CRRAMMETL', 'ZINC', 7),
  ('ZOMB:GBGMZVSIHG7QPMD2I7DYLNTYN3KSFEP47E32C7YCDGCWV4X5NLYVM3M7', 'classic', 'ZOMB:GBGMZVSIHG7QPMD2I7DYLNTYN3KSFEP47E32C7YCDGCWV4X5NLYVM3M7', 'ZOMB', 7),
  ('Zi:GDBNNE67F54PTUZTCTOQYT5CQZFXA2AX6O5DCA5BVR653OP6KCWGG2Z7', 'classic', 'Zi:GDBNNE67F54PTUZTCTOQYT5CQZFXA2AX6O5DCA5BVR653OP6KCWGG2Z7', 'Zi', 7),
  ('native', 'classic', 'native', 'XLM', 7),
  ('oUSD:GBIWJGAOSFC4KUPHXM573TKTWHMI7VW7D4GCHYZYH243Q6HVBV7ORBIT', 'classic', 'oUSD:GBIWJGAOSFC4KUPHXM573TKTWHMI7VW7D4GCHYZYH243Q6HVBV7ORBIT', 'oUSD', 7),
  ('yBTC:GBUVRNH4RW4VLHP4C5MOF46RRIRZLAVHYGX45MVSTKA2F6TMR7E7L6NW', 'classic', 'yBTC:GBUVRNH4RW4VLHP4C5MOF46RRIRZLAVHYGX45MVSTKA2F6TMR7E7L6NW', 'yBTC', 7),
  ('yETH:GDYQNEF2UWTK4L6HITMT53MZ6F5QWO3Q4UVE6SCGC4OMEQIZQQDERQFD', 'classic', 'yETH:GDYQNEF2UWTK4L6HITMT53MZ6F5QWO3Q4UVE6SCGC4OMEQIZQQDERQFD', 'yETH', 7),
  ('yUSDC:GDGTVWSM4MGS4T7Z6W4RPWOCHE2I6RDFCIFZGS3DOA63LWQTRNZNTTFF', 'classic', 'yUSDC:GDGTVWSM4MGS4T7Z6W4RPWOCHE2I6RDFCIFZGS3DOA63LWQTRNZNTTFF', 'yUSDC', 7),
  ('yXLM:GARDNV3Q7YGT4AKSDF25LT32YSCCW4EV22Y2TV3I2PU2MMXJTEDL5T55', 'classic', 'yXLM:GARDNV3Q7YGT4AKSDF25LT32YSCCW4EV22Y2TV3I2PU2MMXJTEDL5T55', 'yXLM', 7)
) AS t(token, kind, asset, symbol, decimals)
), raw AS (
  SELECT *, protocol = 'aquarius' AND action = 'pool_deposit'
            AND closed_at < TIMESTAMP '2026-09-01 00:00:00 UTC' AS legacy_layout
  FROM (
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_blend_activity_archive WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_blend_activity WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_aquarius_activity_archive WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_aquarius_activity WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_soroswap_activity_archive WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_soroswap_activity WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_phoenix_activity_archive WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_phoenix_activity WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_fxdao_activity_archive WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_fxdao_activity WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_etherfuse_activity_archive WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_etherfuse_activity WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_sushiswap_activity_archive WHERE row_kind = 'activity' AND role = 'lp'
UNION ALL
SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, amount_a, token_b, amount_b FROM dune.paltalabs.result_scf_sushiswap_activity WHERE row_kind = 'activity' AND role = 'lp'
  )
), lp AS (
  SELECT protocol, contract_id, closed_at, tx_hash, user_address, action, pool, token_a, token_b, legacy_layout,
         CASE WHEN legacy_layout THEN amount_b ELSE amount_a END AS amount_a,
         CASE WHEN legacy_layout THEN NULL ELSE amount_b END AS amount_b,
         ROW_NUMBER() OVER (ORDER BY closed_at, tx_hash, user_address, action, pool, token_a, amount_a) AS lp_row
  FROM raw
), legs AS (
  SELECT lp_row, 'a' AS leg, token_a AS token, amount_a AS amount, CAST(closed_at AT TIME ZONE 'UTC' AS DATE) AS day FROM lp
  UNION ALL
  SELECT lp_row, 'b', token_b, amount_b, CAST(closed_at AT TIME ZONE 'UTC' AS DATE) FROM lp
), valued AS (
  SELECT l.lp_row, l.leg,
         ABS(CAST(l.amount AS DOUBLE)) * power(10, 7 - COALESCE(t.decimals, 7)) AS token_amount,
         max_by(p.price_usd, p.day) AS price_usd, max_by(p.price_source, p.day) AS price_source
  FROM legs l
  LEFT JOIN tokens t ON t.token = l.token
  LEFT JOIN dune.paltalabs.result_scf_token_prices p ON p.token = l.token AND p.day <= l.day AND p.day >= l.day - INTERVAL '7' DAY
  WHERE l.token IS NOT NULL AND l.amount IS NOT NULL
  GROUP BY l.lp_row, l.leg, l.amount, t.decimals
), pivot AS (
  SELECT lp_row,
         MAX(token_amount) FILTER (WHERE leg = 'a') AS token_amount_a, MAX(price_usd) FILTER (WHERE leg = 'a') AS price_a,
         MAX(token_amount) FILTER (WHERE leg = 'b') AS token_amount_b, MAX(price_usd) FILTER (WHERE leg = 'b') AS price_b,
         array_join(array_distinct(array_agg(price_source) FILTER (WHERE price_source IS NOT NULL)), ',') AS price_sources
  FROM valued GROUP BY 1
)
SELECT lp.protocol, lp.contract_id, lp.pool, lp.closed_at, CAST(lp.closed_at AT TIME ZONE 'UTC' AS DATE) AS day,
       lp.tx_hash, lp.user_address, lp.action, CASE WHEN action IN ('deposit', 'pool_deposit', 'provide_liquidity', 'add_liquidity', 'locking_deposit') THEN 'add' WHEN action IN ('withdraw', 'pool_withdraw', 'withdraw_liquidity', 'remove_liquidity', 'locking_withdraw', 'collect') THEN 'remove' ELSE 'other' END AS direction,
       lp.token_a, v.token_amount_a, v.price_a, v.token_amount_a * v.price_a AS usd_a,
       lp.token_b, v.token_amount_b, v.price_b, v.token_amount_b * v.price_b AS usd_b,
       CASE WHEN lp.legacy_layout THEN 2 * v.token_amount_a * v.price_a
            WHEN lp.protocol = 'sushiswap' THEN COALESCE(v.token_amount_a * v.price_a, 0) + COALESCE(v.token_amount_b * v.price_b, 0)
            WHEN v.token_amount_a * v.price_a > 0 AND v.token_amount_b * v.price_b > 0
             AND GREATEST(v.token_amount_a * v.price_a, v.token_amount_b * v.price_b)
               > 10 * LEAST(v.token_amount_a * v.price_a, v.token_amount_b * v.price_b)
              THEN 2 * LEAST(v.token_amount_a * v.price_a, v.token_amount_b * v.price_b)
            WHEN v.token_amount_a > 0 AND v.token_amount_b > 0 AND (v.price_a IS NULL) <> (v.price_b IS NULL)
              THEN 2 * COALESCE(v.token_amount_a * v.price_a, v.token_amount_b * v.price_b)
            ELSE COALESCE(v.token_amount_a * v.price_a, 0) + COALESCE(v.token_amount_b * v.price_b, 0) END AS usd_total,
       CASE WHEN lp.legacy_layout THEN 'legacy_2x_a'
            WHEN lp.protocol = 'sushiswap' THEN 'sum'
            WHEN v.token_amount_a * v.price_a > 0 AND v.token_amount_b * v.price_b > 0
             AND GREATEST(v.token_amount_a * v.price_a, v.token_amount_b * v.price_b)
               > 10 * LEAST(v.token_amount_a * v.price_a, v.token_amount_b * v.price_b) THEN 'capped_2x_min'
            WHEN v.token_amount_a > 0 AND v.token_amount_b > 0 AND (v.price_a IS NULL) <> (v.price_b IS NULL) THEN 'one_leg_2x'
            ELSE 'sum' END AS usd_method,
       CASE WHEN lp.token_a IS NULL AND lp.token_b IS NULL THEN 'no_tokens'
            WHEN (lp.token_a IS NULL OR v.price_a IS NOT NULL OR COALESCE(v.token_amount_a, 0) = 0)
             AND (lp.token_b IS NULL OR v.price_b IS NOT NULL OR COALESCE(v.token_amount_b, 0) = 0) THEN 'priced'
            WHEN v.price_a IS NOT NULL OR v.price_b IS NOT NULL THEN 'partial'
            ELSE 'unpriced' END AS valuation,
       v.price_sources, CURRENT_TIMESTAMP AS refreshed_at
FROM lp LEFT JOIN pivot v ON v.lp_row = lp.lp_row
